/**
 * Tabs (spec/02 §4.4): a row with a 1 dp border hairline under its whole width, tabs from the start edge, each ≥ 48 dp,
 * 16 dp at the sides, the word in label textMuted (hover text); selected = the 3 dp accent bottom edge + link + title
 * weight; the inset focus ring. [disabledTabs]: the word textSubtle, no target, skipped by the keys (a selected one,
 * which the caller should not pass, keeps the edge in borderStrong, as SbSegmented). [label] names the row
 * for TalkBack. Keys: one Tab stop (the selected tab); ← → with wrap (swapped right to left), Home / End; the tab that
 * gets the focus is selected at once ([onSelect]). The row scrolls sideways when it is wider than the screen.
 */
@Composable
fun SbTabs(
    tabs: List<String>,
    selectedIndex: Int,
    onSelect: (Int) -> Unit,
    label: String,
    modifier: Modifier = Modifier,
    disabledTabs: Set<Int> = emptySet(),
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val rtl = LocalLayoutDirection.current == LayoutDirection.Rtl
    val usable = tabs.indices.filter { it !in disabledTabs }
    val start = if (selectedIndex in usable) selectedIndex else usable.firstOrNull() ?: -1
    var stop by remember(start) { mutableStateOf(start) }
    val requesters = remember(tabs.size) { List(tabs.size) { FocusRequester() } }
    Box(
        modifier
            .fillMaxWidth()
            .drawBehind {
                val w = t.borderWidth.hairline.toPx()
                drawRect(c.border, Offset(0f, size.height - w), Size(size.width, w))
            },
    ) {
        Row(
            Modifier
                .horizontalScroll(rememberScrollState())
                .selectableGroup()
                .semantics {
                    contentDescription = label
                    isTraversalGroup = true
                },
        ) {
            tabs.forEachIndexed { i, word ->
                val interaction = remember { MutableInteractionSource() }
                val hovered by interaction.collectIsHoveredAsState()
                val on = i in usable
                val isSelected = i == selectedIndex
                val ink = when {
                    !on -> c.textSubtle
                    isSelected -> c.link
                    hovered -> c.text
                    else -> c.textMuted
                }
                Box(
                    Modifier
                        .heightIn(min = t.size.targetTouch)
                        .sbCurrentEdge(isSelected, SbEdge.Bottom, if (on) c.accent else c.borderStrong, t.borderWidth.strong)
                        .sbFocusRingInset(interaction)
                        .focusRequester(requesters[i])
                        .focusProperties { if (i != stop) canFocus = false }
                        .onPreviewKeyEvent { e ->
                            val to = sbRowKey(e, i, usable, rtl, homeEnd = true) ?: return@onPreviewKeyEvent false
                            stop = to
                            if (to != selectedIndex) onSelect(to)
                            requesters[to].requestFocus()
                            true
                        }
                        .selectable(
                            selected = isSelected,
                            interactionSource = interaction,
                            indication = null,
                            enabled = on,
                            role = Role.Tab,
                            onClick = { onSelect(i) },
                        )
                        .padding(horizontal = t.space.s4),
                    contentAlignment = Alignment.Center,
                ) {
                    Text(
                        word,
                        style = ty.label.copy(fontWeight = if (isSelected) ty.title.fontWeight else ty.label.fontWeight),
                        color = ink,
                        maxLines = 1,
                        softWrap = false,
                    )
                }
            }
        }
    }
}
